namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;
    private readonly Lock _lock = new();

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                    "Stretch dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly over the dough, leaving a 1-inch border.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10–12 minutes until the crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil before serving."
                ],
                TotalRatings = 12, RatingSum = 53
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Cumin", "Tomato sauce", "Heavy cream", "Garlic", "Ginger", "Onion"],
                Steps = [
                    "Marinate chicken in yogurt, garam masala, and cumin for at least 1 hour.",
                    "Grill or broil the marinated chicken until charred and cooked through.",
                    "Sauté diced onion, garlic, and ginger in oil until softened.",
                    "Add tomato sauce and spices; simmer for 15 minutes.",
                    "Stir in heavy cream, then add the cooked chicken pieces.",
                    "Simmer together for 10 minutes and serve over basmati rice."
                ],
                TotalRatings = 8, RatingSum = 38
            },
            new Recipe
            {
                Id = 3, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = [
                    "Brown ground beef in a skillet over medium-high heat.",
                    "Add taco seasoning and water; simmer until thickened.",
                    "Warm tortillas in a dry skillet or microwave.",
                    "Fill tortillas with seasoned beef.",
                    "Top with shredded lettuce, diced tomato, cheese, sour cream, and salsa."
                ],
                TotalRatings = 15, RatingSum = 62
            },
            new Recipe
            {
                Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Rich and creamy pasta with pancetta, egg, and Parmesan.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper", "Salt"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente; reserve 1 cup pasta water.",
                    "Crisp pancetta in a large skillet over medium heat.",
                    "Whisk eggs and grated Parmesan together in a bowl.",
                    "Toss hot drained pasta with the pancetta in the skillet (off heat).",
                    "Pour the egg mixture over the pasta and toss quickly, adding pasta water as needed.",
                    "Season generously with black pepper and serve immediately."
                ],
                TotalRatings = 10, RatingSum = 45
            },
            new Recipe
            {
                Id = 5, Title = "Pad Thai", Category = "Thai",
                Description = "Stir-fried rice noodles with shrimp, peanuts, and tangy tamarind sauce.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes; drain.",
                    "Mix tamarind paste, fish sauce, and sugar for the sauce.",
                    "Stir-fry shrimp in a hot wok until pink; set aside.",
                    "Scramble eggs in the wok, then add noodles and sauce.",
                    "Toss everything together with bean sprouts and green onions.",
                    "Serve topped with crushed peanuts and lime wedges."
                ],
                TotalRatings = 6, RatingSum = 27
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and zesty avocado dip, perfect as a snack or side.",
                Ingredients = ["Avocados", "Lime juice", "Red onion", "Cilantro", "Jalapeño", "Tomato", "Salt"],
                Steps = [
                    "Halve and pit the avocados; scoop flesh into a bowl.",
                    "Mash with a fork to desired consistency.",
                    "Stir in finely diced onion, jalapeño, tomato, and cilantro.",
                    "Add lime juice and salt to taste.",
                    "Serve immediately with tortilla chips."
                ],
                TotalRatings = 20, RatingSum = 88
            },
            new Recipe
            {
                Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Description = "Classic chewy cookies loaded with chocolate chips.",
                Ingredients = ["Butter", "Sugar", "Brown sugar", "Eggs", "Vanilla extract", "All-purpose flour", "Baking soda", "Salt", "Chocolate chips"],
                Steps = [
                    "Preheat oven to 375°F (190°C).",
                    "Cream butter with both sugars until light and fluffy.",
                    "Beat in eggs one at a time, then add vanilla.",
                    "Whisk flour, baking soda, and salt; gradually mix into the wet ingredients.",
                    "Fold in chocolate chips.",
                    "Drop rounded tablespoons onto baking sheets.",
                    "Bake for 9–11 minutes until edges are golden. Cool on the pan for 5 minutes."
                ],
                TotalRatings = 25, RatingSum = 118
            },
            new Recipe
            {
                Id = 8, Title = "Miso Soup", Category = "Japanese",
                Description = "A warm, comforting soup with tofu, seaweed, and umami-rich miso.",
                Ingredients = ["Dashi stock", "White miso paste", "Silken tofu", "Wakame seaweed", "Green onions"],
                Steps = [
                    "Bring dashi stock to a gentle simmer in a saucepan.",
                    "Rehydrate wakame in water for 5 minutes; drain.",
                    "Cut tofu into small cubes.",
                    "Ladle a small amount of hot dashi into a bowl; dissolve miso paste into it.",
                    "Pour the miso mixture back into the pot (do not boil).",
                    "Add tofu and wakame; heat through for 1–2 minutes.",
                    "Serve garnished with sliced green onions."
                ],
                TotalRatings = 5, RatingSum = 22
            },
        ];
        _nextId = 9;
    }

    public List<string> GetCategories()
    {
        lock (_lock)
        {
            return _recipes.Select(r => r.Category).Distinct().Order().ToList();
        }
    }

    public List<Recipe> GetByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetById(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;

        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null)
            {
                recipe.TotalRatings++;
                recipe.RatingSum += stars;
            }
        }
    }

    public Recipe AddRecipe(string title, string ingredients, string steps)
    {
        lock (_lock)
        {
            var recipe = new Recipe
            {
                Id = _nextId++,
                Title = title.Trim(),
                Category = "Community",
                Description = "A community-submitted recipe.",
                Ingredients = ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
                Steps = steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            };
            _recipes.Add(recipe);
            return recipe;
        }
    }
}

@using RecipeShare.Services
@rendermode InteractiveServer
@inject RecipeService Recipes

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="star-btn @(star <= _selectedRating ? "selected" : "")"
                @onclick="() => Rate(star)"
                disabled="@_hasRated"
                title="Rate @star star@(star > 1 ? "s" : "")">
            @(star <= _selectedRating ? "★" : "☆")
        </button>
    }
    <span class="rating-info">
        @if (_hasRated)
        {
            <span class="text-success">Thanks for rating!</span>
        }
        @if (_average > 0)
        {
            <span>@_average.ToString("0.0") avg (@_totalRatings ratings)</span>
        }
    </span>
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    private int _selectedRating;
    private bool _hasRated;
    private double _average;
    private int _totalRatings;

    protected override void OnInitialized()
    {
        LoadRating();
    }

    private void Rate(int stars)
    {
        if (_hasRated) return;
        Recipes.AddRating(RecipeId, stars);
        _selectedRating = stars;
        _hasRated = true;
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = Recipes.GetById(RecipeId);
        if (recipe is not null)
        {
            _average = recipe.AverageRating;
            _totalRatings = recipe.TotalRatings;
        }
    }
}

@page "/category/{CategoryName}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (_recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        @if (recipe.TotalRatings > 0)
                        {
                            <p class="text-warning mb-2">
                                @GetStars(recipe.AverageRating) <small class="text-muted">(@recipe.TotalRatings)</small>
                            </p>
                        }
                    </div>
                    <div class="card-footer">
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-link">← Back to Home</a>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> _recipes = [];

    protected override void OnInitialized()
    {
        _recipes = Recipes.GetByCategory(CategoryName);
    }

    private static string GetStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService Recipes

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeShare</PageTitle>
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="/" class="btn btn-link">← Back to Home</a>
}
else
{
    <PageTitle>@_recipe.Title — RecipeShare</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p class="lead text-muted">@_recipe.Description</p>

    <StarRating RecipeId="@_recipe.Id" />

    <div class="row mt-4">
        <div class="col-md-5">
            <h3>Ingredients</h3>
            <ul class="list-group list-group-flush">
                @foreach (var ingredient in _recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>
        <div class="col-md-7">
            <h3>Steps</h3>
            <ol class="list-group list-group-numbered list-group-flush">
                @foreach (var step in _recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <div class="mt-4">
        <a href="/category/@_recipe.Category" class="btn btn-outline-secondary">← Back to @_recipe.Category</a>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = Recipes.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService Recipes
@inject NavigationManager Nav

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "<strong>@_submittedTitle</strong>" has been added.
        <a href="/recipe/@_submittedId">View it here</a>.
    </div>
}

<EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g. Grandma's Apple Pie" />
        <ValidationMessage For="() => _model.Title" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="_model.Ingredients"
                       placeholder="One ingredient per line&#10;e.g.&#10;2 cups flour&#10;1 cup sugar&#10;3 large apples" />
        <ValidationMessage For="() => _model.Ingredients" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_model.Steps"
                       placeholder="One step per line&#10;e.g.&#10;Preheat oven to 350°F&#10;Mix flour and sugar&#10;Slice apples and arrange in pie dish" />
        <ValidationMessage For="() => _model.Steps" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private string _submittedTitle = string.Empty;
    private int _submittedId;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_model.Title) ||
            string.IsNullOrWhiteSpace(_model.Ingredients) ||
            string.IsNullOrWhiteSpace(_model.Steps))
            return;

        var recipe = Recipes.AddRecipe(_model.Title, _model.Ingredients, _model.Steps);
        _submittedTitle = recipe.Title;
        _submittedId = recipe.Id;
        _submitted = true;
        _model = new();
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list at least one ingredient.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}

