@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private string _submittedTitle = string.Empty;
    private int _submittedId;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_model.Title) ||
            string.IsNullOrWhiteSpace(_model.Ingredients) ||
            string.IsNullOrWhiteSpace(_model.Steps))
            return;

        var recipe = Recipes.AddRecipe(_model.Title, _model.Ingredients, _model.Steps);
        _submittedTitle = recipe.Title;
        _submittedId = recipe.Id;
        _submitted = true;
        _model = new();
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list at least one ingredient.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}

