using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;
    private readonly Lock _lock = new();

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                    "Stretch dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly over the dough, leaving a 1-inch border.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10–12 minutes until the crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil before serving."
                ],
                TotalRatings = 12, RatingSum = 53
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Cumin", "Tomato sauce", "Heavy cream", "Garlic", "Ginger", "Onion"],
                Steps = [
                    "Marinate chicken in yogurt, garam masala, and cumin for at least 1 hour.",
                    "Grill or broil the marinated chicken until charred and cooked through.",
                    "Sauté diced onion, garlic, and ginger in oil until softened.",
                    "Add tomato sauce and spices; simmer for 15 minutes.",
                    "Stir in heavy cream, then add the cooked chicken pieces.",
                    "Simmer together for 10 minutes and serve over basmati rice."
                ],
                TotalRatings = 8, RatingSum = 38
            },
            new Recipe
            {
                Id = 3, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = [
                    "Brown ground beef in a skillet over medium-high heat.",
                    "Add taco seasoning and water; simmer until thickened.",
                    "Warm tortillas in a dry skillet or microwave.",
                    "Fill tortillas with seasoned beef.",
                    "Top with shredded lettuce, diced tomato, cheese, sour cream, and salsa."
                ],
                TotalRatings = 15, RatingSum = 62
            },
            new Recipe
            {
                Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Rich and creamy pasta with pancetta, egg, and Parmesan.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper", "Salt"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente; reserve 1 cup pasta water.",
                    "Crisp pancetta in a large skillet over medium heat.",
                    "Whisk eggs and grated Parmesan together in a bowl.",
                    "Toss hot drained pasta with the pancetta in the skillet (off heat).",
                    "Pour the egg mixture over the pasta and toss quickly, adding pasta water as needed.",
                    "Season generously with black pepper and serve immediately."
                ],
                TotalRatings = 10, RatingSum = 45
            },
            new Recipe
            {
                Id = 5, Title = "Pad Thai", Category = "Thai",
                Description = "Stir-fried rice noodles with shrimp, peanuts, and tangy tamarind sauce.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes; drain.",
                    "Mix tamarind paste, fish sauce, and sugar for the sauce.",
                    "Stir-fry shrimp in a hot wok until pink; set aside.",
                    "Scramble eggs in the wok, then add noodles and sauce.",
                    "Toss everything together with bean sprouts and green onions.",
                    "Serve topped with crushed peanuts and lime wedges."
                ],
                TotalRatings = 6, RatingSum = 27
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and zesty avocado dip, perfect as a snack or side.",
                Ingredients = ["Avocados", "Lime juice", "Red onion", "Cilantro", "Jalapeño", "Tomato", "Salt"],
                Steps = [
